direct_gen_code:
import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))
    a.sort()
    total = sum(a)
    if total % 2 == 1:
        print("No")
        return
    target = total // 2
    dp = 1
    for x in a:
        dp |= dp << x
    if (dp >> target) & 1:
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    solve()

